const required = ['customer_name', 'items'];
for (const field of required) if (!$json[field]) throw new Error(`${field} is required`);
if (!Array.isArray($json.items) || $json.items.length === 0) throw new Error('at least one item is required');
return [{ json: $json }];

const items = $json.items || [];
const discount = Number($json.discount || 0);
const additionalFee = Number($json.additional_fee || 0);

if (discount < 0 || additionalFee < 0) {
  throw new Error('discount and additional_fee must be non-negative');
}

let subtotal = 0;
const calculatedItems = items.map((item, index) => {
  const quantity = Number(item.quantity);
  const unitPrice = Number(item.unit_price);
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new Error(`item ${index + 1} quantity must be a positive integer`);
  }
  if (!Number.isInteger(unitPrice) || unitPrice < 0) {
    throw new Error(`item ${index + 1} unit_price must be a non-negative integer`);
  }
  const lineTotal = quantity * unitPrice;
  subtotal += lineTotal;
  return {
    ...item,
    sort_order: index + 1,
    quantity,
    unit_price: unitPrice,
    line_total: lineTotal,
  };
});

const grandTotal = subtotal - discount + additionalFee;
if (grandTotal < 0) {
  throw new Error('grand_total must be non-negative');
}

return [
  {
    json: {
      ...$json,
      items: calculatedItems,
      subtotal,
      discount,
      additional_fee: additionalFee,
      grand_total: grandTotal,
    },
  },
];

const crypto = require('crypto');

function normalizeText(value) {
  if (value === null || value === undefined) return null;
  return String(value).normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
}

function canonicalInt(value) {
  if (value === null || value === undefined || value === '') return 0;
  const normalized = String(value).trim().toLowerCase().replace(/\s+/g, '');
  if (normalized.includes('juta')) {
    const amount = normalized.replace('rp', '').replace('juta', '').replace(',', '.');
    return Math.round(Number.parseFloat(amount) * 1000000);
  }
  return Number.parseInt(normalized.replace(/[^\d-]/g, ''), 10);
}

const canonical = {
  customer: normalizeText($json.customer_name || $json.customer?.name),
  payment_type: String($json.payment_type || $json.payment?.type || '').trim().toUpperCase(),
  discount: canonicalInt($json.discount || 0),
  additional_fee: canonicalInt($json.additional_fee || 0),
  items: ($json.items || []).map((item) => ({
    trip_date: item.trip_date || null,
    vehicle_type: normalizeText(item.vehicle_type),
    quantity: canonicalInt(item.quantity),
    pickup: normalizeText(item.pickup),
    destination: normalizeText(item.destination),
    unit_price: canonicalInt(item.unit_price),
  })).sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
};

const payload = JSON.stringify(canonical);
const contentFingerprint = crypto.createHash('sha256').update(payload).digest('hex');

return [{ json: { ...$json, canonical_business_data: canonical, content_fingerprint: contentFingerprint } }];

function rupiah(amount) {
  return 'Rp' + Number(amount || 0).toLocaleString('id-ID');
}

function formatDate(value) {
  if (!value) return '-';
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(value));
}

const lines = [
  '📄 PRATINJAU INVOICE',
  '',
  'Kepada:',
  $json.customer_name,
  '',
];

for (const item of $json.items || []) {
  lines.push(formatDate(item.trip_date));
  lines.push(`${item.vehicle_type}`);
  lines.push(`${item.quantity} unit × ${rupiah(item.unit_price)}`);
  lines.push(`= ${rupiah(item.line_total)}`);
  lines.push(`${item.pickup || '-'} → ${item.destination || '-'}`);
  lines.push('');
}

lines.push('TOTAL');
lines.push(rupiah($json.grand_total));
lines.push('');
lines.push('Pembayaran:');
lines.push($json.payment_type === 'FULL_PAYMENT' ? 'LUNAS / FULL PAYMENT' : $json.payment_type);

if (($json.included || []).length) {
  lines.push('');
  lines.push('Termasuk:');
  for (const item of $json.included) lines.push(`✓ ${item}`);
}

if (($json.excluded || []).length) {
  lines.push('');
  lines.push('Tidak termasuk:');
  for (const item of $json.excluded) lines.push(`- ${item}`);
}

lines.push('');
lines.push('Sudah benar?');
lines.push('Balas: setuju atau tulis revisinya.');

return [{ json: { ...$json, preview_text: lines.join('\n') } }];
